.pdp-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pdp-root,.pdp-root *,.pdp-root *::before,.pdp-root *::after{box-sizing:border-box}
.pdp-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pdp-root img{display:block;border:0;max-width:none}
.pdp-root > [data-node-id]{will-change:transform}
.pdp-root [hidden]{display:none!important}
.pdp-root [data-sh-theme="dark"]{display:none!important}
.pdp-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.pdp-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.pdp-root .n3293_6119{align-content:stretch;display:flex;gap:11px;height:28px;align-items:center;position:relative;flex-shrink:0;width:206px}
.pdp-root .n3293_5292{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 30%, transparent);align-content:stretch;display:flex;gap:5px;align-items:center;justify-content:center;padding-left:8px;padding-right:8px;padding-top:5px;padding-bottom:5px;position:relative;border-radius:15px;flex-shrink:0}
.pdp-root .n3293_5293{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:18px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #303a46);font-size:16px;text-align:center;white-space:nowrap;width:67px}
.pdp-root .n3293_5291{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:20px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #676767);font-size:18px;white-space:nowrap;width:112px}
.pdp-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.pdp-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.pdp-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > div{background:linear-gradient(180deg,var(--wa-bg, #0d1117) 0%,var(--wa-bg, #111821) 100%)!important}
.pdp-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > img{opacity:.04!important;filter:invert(1)}
.pdp-root[data-theme="dark"] [data-name="Stage/3D Scene"] img{filter:brightness(.9) saturate(.95) contrast(1.03)}
.pdp-root[data-theme="dark"] [data-name="Stage/Building Image"] img{filter:brightness(.86) contrast(1.04)}
.pdp-root[data-theme="dark"] [data-name="Side Rail"],.pdp-root[data-theme="dark"] [data-name="Filter Panel"] [data-name="Rectangle 4"]{background:color-mix(in srgb, var(--wa-bg, rgb(20 23 29)) 84%, transparent)!important;box-shadow:0 0 0 1px rgba(255,255,255,.07),0 12px 28px rgba(0,0,0,.35)!important;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.pdp-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Background"],.pdp-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Header Background"]{background:var(--wa-bg, #12151b)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.07)!important}
.pdp-root[data-theme="dark"] svg [fill="#FCFCFC"]:not(mask *),.pdp-root[data-theme="dark"] svg [fill="#fcfcfc"]:not(mask *),.pdp-root[data-theme="dark"] svg [fill="white"]:not(mask *),.pdp-root[data-theme="dark"] svg [fill="#F9F9F9"]:not(mask *){fill:var(--wa-surface, #15181e)}
.pdp-root[data-theme="dark"] svg [stroke="#F1F1F1"]:not(mask *),.pdp-root[data-theme="dark"] svg [stroke="#f1f1f1"]:not(mask *),.pdp-root[data-theme="dark"] svg [fill="#F1F1F1"]:not(mask *){stroke:var(--wa-line, #2a2e36)}
.pdp-root[data-theme="dark"] svg path[fill="#F1F1F1"]:not(mask *){fill:var(--wa-surface, #2a2e36)}
.pdp-root[data-theme="dark"] [data-name="Event Log"] [data-name^="Row/"]:hover,.pdp-root[data-theme="dark"] [data-name="Event Log"] [data-name="grid-row"]:hover{filter:brightness(1.15)}
.pdp-root[data-theme="dark"] [data-name="Tooltip Group"] [data-name^="Tooltip/"] p{color:var(--wa-text, #e6ebf2)!important}
.pdp-root[data-theme="dark"] [data-name^="Category/"] img{content:normal!important}
.pdp-root[data-theme="dark"] .n3293_5292{background-color:color-mix(in srgb, var(--wa-surface, rgb(23 26 32)) 45%, transparent)}
.pdp-root[data-theme="dark"] .n3293_5293{color:var(--wa-text, #e6ebf2)}
.pdp-root[data-theme="dark"] .n3293_5291{color:var(--wa-text-sub, #a3a8b0)}
